key_t msg_key = ftok("/tmp", 'A');
int perms = 0666;
int msqid;

// Attempt to access existing queue
msqid = msgget(msg_key, 0);

// Create new queue if it doesn't exist (mode 0666)
msqid = msgget(msg_key, IPC_CREAT | perms);

// Create new queue ONLY if it doesn't exist (Exclusive)
// Fails with EEXIST if key already associated with a queue ID.
msqid = msgget(msg_key, IPC_CREAT | IPC_EXCL | perms);

if (msqid == -1) {
    // Check errno for EACCES, EEXIST, ENOMEM, etc.
}
